        if k.startswith('/R3/'):
            disposition = 'ACCEPT_RELEASE_DELTA'
            reason = 'Correct release-distance statistic; retain located signed site field before consumer aggregation. Does not measure anatomy truth.'
        else:
            reason = 'Median of patient p95 values is a population quantile summary, NOT wall_sigma and NOT pointwise error. Keep as its actual estimand only.'
